"""Attach permissions to a user profile."""


def build_profile(user, permissions=["read"]):
    """Return a profile dict for `user`.

    If the caller does not pass permissions, the user gets the base ['read'].
    """
    if "admin" in user:
        permissions.append("write")
    return {"user": user, "permissions": permissions}

tests.body:
from profile import build_profile


def test_default_permissions():
    assert build_profile("ada") == {"user": "ada", "permissions": ["read"]}


def test_admin_gets_write():
    assert build_profile("admin-jo") == {"user": "admin-jo", "permissions": ["read", "write"]}

from profile import build_profile


def test_repeated_calls_are_independent():
    build_profile("ada")
    build_profile("admin-x")
    assert build_profile("bob") == {"user": "bob", "permissions": ["read"]}


def test_many_calls_stay_constant():
    results = [build_profile(f"u{i}") for i in range(50)]
    assert all(r["permissions"] == ["read"] for r in results)

from profile import build_profile


def test_caller_permissions_used():
    assert build_profile("ada", ["read", "share"]) == {
        "user": "ada",
        "permissions": ["read", "share"],
    }


def test_caller_list_not_mutated():
    caller = ["read"]
    build_profile("admin-x", caller)
    assert caller == ["read"], "the caller's list was mutated by append"


def test_default_is_not_a_shared_object():
    a = build_profile("a")
    a["permissions"].append("leaked")
    b = build_profile("b")
    assert b["permissions"] == ["read"]

